    nodes {
      eventDate
      adjustmentType
      supplierPartNumber
      quantity
      description
      warehouse{
        warehouseId
        name
        address{
          address1
          address2
          address3
          city
          stateShortName
          country
          postalCode
          }
        }
    }
  }
}

