query dropshipOrders(
  $filter: SupplierDropshipOrderFilterInput,
  $first: Int,
  $after: String,
  $last: Int,
  $before: String,
  $sort: SupplierDropshipOrderSortInput
  ) {
  dropshipOrders(filter: $filter, first: $first, after: $after, last: $last, before: $before, sort: $sort) {
    edges {
      cursor
      node {
        ... on SupplierDropshipOrder {
          purchaseOrderNumber
          createdAt
          customerOrderId
          origin {
            displayName
            marketContext {
              brand
              country
              locale
              channel
              segment
            }
          }
          orderType
          status
          mustShipByDate
          storeName
          shippingInfo {
            shipSpeed
            carrierCode
            poolPointAgent {
              id
              name
            }
            crossDockAgent {
              id
              name
            }
            deliveryAgent {
              id
              name
            }
          }
          warehouseDetails {
            id
            address {
              city
              state
              country
            }
          }
          customer {
            city
            state
            country
          }
          shippingAddress {
            city
            state
            country
          }
          billingAddress {
            city
            state
            country
          }
          lineItems {
            supplierPartNumber
            name
            listingId
            quantity
            pieceCount
            status
            customComment
            isTscaCompliant
            unitPrice {
              amount
              currencyCode
            }
            orderValue {
              amount
              currencyCode
            }
            weight { value unit }
            totalWeight { value unit }
            actualShipDate
            deliveryDate
            event {
              id
              type
              name
              startDate
              endDate
            }
            tasks {
              taskType
              status
              requestedShipSpeed
              requestedShippingAddress {
                city
                state
                country
              }
            }
          }
          tasks {
            taskType
            status
            requestedShipSpeed
            requestedShippingAddress {
              city
              state
              country
            }
          }
        }
        ... on SupplierDropshipOrderIssue {
          purchaseOrderNumber
          code
          message
          remediation
        }
      }
    }
    pageInfo {
      hasNextPage
      endCursor
    }
  }
}

